def fetch_disbursements(base_url):
    """Export every disbursement via the v2 paginated endpoint.

    Windows may overlap at their edges, so deduplicate on `id`.
    Stop when `drained` is true, not when a window is smaller than `limit`.
    """
    disbursements = {}
    url = f"{base_url}/v2/disbursements"
    while True:
        with urllib.request.urlopen(url, timeout=30) as resp:
            data = json.load(resp)
        for d in data["disbursements"]:
            disbursements[d["id"]] = d
        if data["drained"]:
            return list(disbursements.values())
        url = f"{base_url}/v2/disbursements?cursor={urllib.parse.quote(data['cursor'])}"

